import{c as i,S as e,j as r,m as l}from"./chunks/framework.8aa1YH_s.js";const g=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 12: Kelime Türleri - İsimler ve İsim Tamlamaları","description":"","frontmatter":{},"headers":[],"relativePath":"12 Kelime Türleri - İsimler ve İsim Tamlamaları.md","filePath":"12 Kelime Türleri - İsimler ve İsim Tamlamaları.md"}'),n={name:"12 Kelime Türleri - İsimler ve İsim Tamlamaları.md"};function m(s,a,t,o,k,d){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="turk-dil-bilgisi-serisi-12-kelime-turleri-isimler-ve-isim-tamlamaları" tabindex="-1">Türk Dil Bilgisi Serisi - 12: Kelime Türleri - İsimler ve İsim Tamlamaları <a class="header-anchor" href="#turk-dil-bilgisi-serisi-12-kelime-turleri-isimler-ve-isim-tamlamaları" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 12: Kelime Türleri - İsimler ve İsim Tamlamaları”">​</a></h1><p>Şekil bilgisinin o katı kök ve ek kurallarını geride bıraktık. Bu yazımızla birlikte, kelimelerin cümle içindeki görevlerine ve yüklendikleri anlamlara göre büründükleri kimlikleri inceleyeceğimiz <strong>Kelime Türleri</strong> konusuna giriş yapıyoruz.</p><p>Prof. Dr. Muharrem Ergin’e göre Türkçede kelimeler temelde iki büyük nehre ayrılır: <strong>İsim soylu kelimeler</strong> ve <strong>Fiil soylu kelimeler</strong>. Bu bölümümüzde isim soylu kelimelerin anası olan <strong>İsimleri (Adları)</strong> ve dilimizin ifade gücünü katlayan <strong>İsim Tamlamalarını</strong> ele alacağız.</p><hr><h2 id="_1-isim-ad-nedir" tabindex="-1">1. İsim (Ad) Nedir? <a class="header-anchor" href="#_1-isim-ad-nedir" aria-label="Permalink to “1. İsim (Ad) Nedir?”">​</a></h2><p>Kainattaki canlı veya cansız tüm varlıkları, somut nesneleri, soyut kavramları, duygu, düşünce ve durumları karşılayan kelimelere <strong>isim</strong> denir. İsimler iş, oluş veya hareket bildirmezler; sadece var olanı niteler ve adlandırırlar.</p><p>Muharrem Ergin sistematiğinde isimler 3 ana kritere göre sınıflandırılır:</p><h3 id="a-varlıklara-verilislerine-gore-isimler" tabindex="-1">A) Varlıklara Verilişlerine Göre İsimler <a class="header-anchor" href="#a-varlıklara-verilislerine-gore-isimler" aria-label="Permalink to “A) Varlıklara Verilişlerine Göre İsimler”">​</a></h3><ol><li><strong>Özel İsimler:</strong> Dünyada tek olan, eşi benzeri bulunmayan şahsiyet, mekan, kurum, din, dil veya devlet gibi varlıklara verilen adlardır. (Örn: <em>Mustafa Kemal Atatürk, Türkiye, Türkçe, İstanbul, Beşiktaş</em>).</li><li><strong>Cins (Tür) İsimleri:</strong> Aynı türden olan, aynı özellikleri taşıyan birden fazla varlığın ortak adıdır. (Örn: <em>Taş, ağaç, nehir, kitap, insan, kedi</em>).</li></ol><h3 id="b-varlıkların-maddelerine-tabiatlarına-gore-isimler" tabindex="-1">B) Varlıkların Maddelerine (Tabiatlarına) Göre İsimler <a class="header-anchor" href="#b-varlıkların-maddelerine-tabiatlarına-gore-isimler" aria-label="Permalink to “B) Varlıkların Maddelerine (Tabiatlarına) Göre İsimler”">​</a></h3><ol><li><strong>Somut İsimler:</strong> Beş duyu organımızdan en az biriyle algılayabildiğimiz varlıkların adıdır. (Örn: <em>Rüzgâr, ses, ışık, masa, soğuk</em>).</li><li><strong>Soyut İsimler:</strong> Zihnimizle, inancımızla veya duygularımızla var olduğunu kabul ettiğimiz, madde dünyasında yer kaplamayan kavramların adıdır. (Örn: <em>Aşk, keder, melek, akıl, rüya, korku</em>).</li></ol><h3 id="c-varlıkların-sayılarına-gore-isimler" tabindex="-1">C) Varlıkların Sayılarına Göre İsimler <a class="header-anchor" href="#c-varlıkların-sayılarına-gore-isimler" aria-label="Permalink to “C) Varlıkların Sayılarına Göre İsimler”">​</a></h3><ol><li><strong>Tekil İsimler:</strong> Çoğul eki (<code>-lar / -ler</code>) almamış ve tek bir varlığı karşılayan isimlerdir. (Örn: <em>Öğrenci, ağaç, kalem</em>).</li><li><strong>Çoğul İsimler:</strong> Çoğul eki alarak aynı varlıktan birden fazlasını ifade eden isimlerdir. (Örn: <em>Öğrenciler, ağaçlar, kalemler</em>).</li><li><strong>Topluluk İsimleri:</strong> Yapıca (şeklen) tekil göründüğü halde, barındırdığı anlam bakımından bir grubu, çokluğu ifade eden isimlerdir. (Örn: <em>Ordu, aile, meclis, sürü, millet, takım</em>).</li></ol><hr><h2 id="_2-isim-tamlamaları-genitif-yapısı" tabindex="-1">2. İsim Tamlamaları (Genitif Yapısı) <a class="header-anchor" href="#_2-isim-tamlamaları-genitif-yapısı" aria-label="Permalink to “2. İsim Tamlamaları (Genitif Yapısı)”">​</a></h2><p>Türkçede tek bir isim, bazen karmaşık bir kavramı veya mülkiyeti ifade etmeye yetmez. En az iki ismin bir araya gelerek, aralarında sahiplik, aitlik veya ilgili olma ilişkisi kurarak oluşturduğu söz öbeklerine <strong>İsim Tamlaması</strong> denir.</p><p>Tamlamada iki temel unsur vardır:</p><ol><li><strong>Tamlayan (İlgi eki alan unsur):</strong> Öbeğin ilk kelimesidir. Eki: <code>-ın, -in, -un, -ün / -nın, -nin...</code></li><li><strong>Tamlanan (İyelik eki alan unsur):</strong> Öbeğin ikinci kelimesidir (Esas unsurdur). Eki: <code>-ı, -i, -u, -ü / -sı, -si...</code></li></ol><p>Muharrem Ergin sistematiğinde isim tamlamaları <strong>3 ana gruba</strong> ayrılır:</p><p>[ İSİM TAMLAMALARI ] | +---------------------+---------------------+ | | | [ Belirtili İ.T. ] [ Belirtisiz İ.T. ] [ Zincirleme İ.T. ]</p><h3 id="_1-belirtili-isim-tamlaması" tabindex="-1">1. Belirtili İsim Tamlaması <a class="header-anchor" href="#_1-belirtili-isim-tamlaması" aria-label="Permalink to “1. Belirtili İsim Tamlaması”">​</a></h3><p>Hem tamlayanın hem de tamlananın kendi eklerini eksiksiz aldığı tamlama türüdür. Çok güçlü ve net bir <strong>sahiplik/aitlik</strong> bildirir. &quot;Kimin?&quot; veya &quot;Nerenin?&quot; sorularına cevap verir.</p><ul><li><em>Formül:</em> <code>[İsim + Tamlayan Eki] + [İsim + Tamlanan Eki]</code></li><li><em>Örnekler:</em><ul><li><em>Çocuğ-<strong>un</strong> kitab-<strong>ı</strong></em></li><li><em>Kapı-<strong>nın</strong> kol-<strong>u</strong></em></li><li><em>Okul-<strong>un</strong> bahçe-<strong>si</strong></em></li></ul></li></ul><h3 id="_2-belirtisiz-isim-tamlaması" tabindex="-1">2. Belirtisiz İsim Tamlaması <a class="header-anchor" href="#_2-belirtisiz-isim-tamlaması" aria-label="Permalink to “2. Belirtisiz İsim Tamlaması”">​</a></h3><p>Tamlayanın (ilk kelimenin) ek <strong>almadığı</strong>, sadece tamlananın (ikinci kelimenin) iyelik eki aldığı tamlama türüdür. Sahiplikten ziyade bir <strong>tür, nitelik, meslek veya araç</strong> kalıbı oluşturur. &quot;Ne?&quot; sorusuna cevap verir.</p><ul><li><em>Formül:</em> <code>[İsim (Eksiz)] + [İsim + Tamlanan Eki]</code></li><li><em>Örnekler:</em><ul><li><em>Türk dil-<strong>i</strong></em> (Türk&#39;ün dili değil, dilin türü)</li><li><em>Okul müdür-<strong>ü</strong></em></li><li><em>Futbol top-<strong>u</strong></em></li><li><em>Sokak lambas-<strong>ı</strong></em></li></ul></li></ul><h3 id="_3-zincirleme-isim-tamlaması" tabindex="-1">3. Zincirleme İsim Tamlaması <a class="header-anchor" href="#_3-zincirleme-isim-tamlaması" aria-label="Permalink to “3. Zincirleme İsim Tamlaması”">​</a></h3><p>En az üç ismin bir araya gelmesiyle oluşan; kendi içinde başka bir isim tamlamasını barındıran tamlama zinciridir. Tamlama içinde tamlama mantığı vardır.</p><ul><li><em>Örnekler:</em><ul><li><code>[Okul bahçesi]</code> (Belirtisiz İ.T.) + kapısı $$\\rightarrow$$ <strong>Okul bahçesinin kapısı</strong></li><li><code>[Çocuğun kitabı]</code> (Belirtili İ.T.) + kapağı $$\\rightarrow$$ <strong>Çocuğun kitabının kapağı</strong></li><li>İstanbul <code>[şehir tiyatroları]</code> $$\\rightarrow$$ <strong>İstanbul şehir tiyatroları</strong></li></ul></li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Prof. Dr. Muharrem Ergin&#39;in penceresinden baktığımızda, isimler dilin adlandırma mekanizmasıdır. Tek başlarına dünyayı etiketleyen bu kelimeler, <strong>İsim Tamlamaları</strong> sayesinde birbirine kenetlenir ve dilde mülkiyet, aidiyet ve kavramsal ilişkiler ağını örer. Türkçenin bu tamlama mantığını çözmek, dilin cümle yapısındaki tüm söz öbeklerini anlamanın temel anahtarıdır.</p><ol start="12"><li>bölümü de sağ salim cebimize koyduk aslanım!</li></ol><p>Serimizin 13. bölümünde, isimlerin önüne gelerek onları renklendiren, şekillendiren ve sayısal olarak belirten harika bir türe geçiyoruz: <strong>&quot;Sıfatlar (Ön Adlar)&quot;</strong>.</p><p>Kaptanın komutunu bekliyorum, geçelim mi?</p>',35)])])}const b=i(n,[["render",m]]);export{g as __pageData,b as default};
